#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

using System;
using System.Runtime.InteropServices;

// Test stackalloc with nint (native-sized integer)
Span<nint> signedSpan = stackalloc nint[5];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = i * 10;

Console.WriteLine($"Span<nint> length: {signedSpan.Length}, sizeof(nint): {sizeof(nint)}");
for (int i = 0; i < signedSpan.Length; i++)
    Console.WriteLine($"  signedSpan[{i}] = {signedSpan[i]}");

// Test stackalloc with nuint (unsigned native-sized integer)
Span<nuint> unsignedSpan = stackalloc nuint[3];
unsignedSpan[0] = (nuint)100;
unsignedSpan[1] = (nuint)200;
unsignedSpan[2] = (nuint)300;

Console.WriteLine($"\nSpan<nuint> length: {unsignedSpan.Length}, sizeof(nuint): {sizeof(nuint)}");
for (int i = 0; i < unsignedSpan.Length; i++)
    Console.WriteLine($"  unsignedSpan[{i}] = {unsignedSpan[i]}");

Console.WriteLine($"\nnint maps to: {typeof(nint)} (IntPtr: {typeof(nint) == typeof(IntPtr)})");
Console.WriteLine($"nuint maps to: {typeof(nuint)} (UIntPtr: {typeof(nuint) == typeof(UIntPtr)})");

